import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { offerDaysRemaining } from "@/lib/offerExpiry";
import { trpc } from "@/lib/trpc";
import { countryCallingCodes, DEFAULT_COUNTRY_CODE } from "@/lib/countryCallingCodes";
import { categoryMeta, formatSyp, toLegacySyp, toNewSyp, type LahzaCategory } from "@shared/lahza";
import { productUnitsForCategory } from "@shared/productUnits";
import ClothingProductFields from "@/components/partner/ClothingProductFields";
import { DEFAULT_STORE_HOURS, STORE_DAY_KEYS, STORE_DAY_LABELS, type StoreHours } from "@shared/storeAvailability";
import { ArrowRight, BadgePercent, FileText, Image as ImageIcon, ImagePlus, Loader2, LocateFixed, LogOut, PackageCheck, PackagePlus, Pencil, Plus, Store, Trash2, X, WalletCards } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";
import { useLocation } from "wouter";

const lahzaWordmarkUrl = "/assets/lahza-logo.svg";
const readImageFile = (file: File) => new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result ?? "")); reader.onerror = () => reject(new Error("تعذر قراءة الصورة")); reader.readAsDataURL(file); });

type AssignedStore = { id: number; name: string; category: LahzaCategory; categoryTitle?: string | null; imageUrl?: string | null; active: boolean; locationLat?: number | null; locationLng?: number | null };
type PartnerData = { id: number; name: string; imageUrl?: string | null; storeOpen: boolean; preparationMinutes: number; workHours?: StoreHours | null; stores: AssignedStore[] };
type PartnerProduct = { id: number; storeId: number | null; name: string; unit: string; unitPrice: number; stockQuantity: number; stockInitialQuantity: number; stockAlertPercent: number; available: boolean; imageUrl?: string | null; imageUrls?: string | null; clothingSizes?: string | null; clothingColors?: string | null; clothingVariantImages?: string | null };
type PartnerOffer = { id: number; storeId: number | null; catalogItemId: number | null; text: string; discountPercent: number; offerPrice: number; imageUrl: string | null; imageStorageKey: string | null; durationDays: number | null; expiresAt: Date | string | null; deletedAt: Date | string | null; active: boolean; featuredStatus: "none" | "pending" | "approved" | "rejected"; featuredReviewNote: string | null };
type WorkReport = { periodStart: Date | string; periodEnd: Date | string; stores: { id: number; name: string }[]; current: { orders: number; completed: number; cancelled: number; sales: number; topProducts: { name: string; quantity: number }[] }; previous: { orders: number; completed: number; cancelled: number; sales: number; topProducts: { name: string; quantity: number }[] }; visits: number; qrVisits: number; directVisits: number };
type StoreTab = "products" | "offers" | "orders" | "accounts";
type PartnerCompletedOrder = { orderId: number; createdAt: Date | string; itemTotal: number; items: { name: string; quantity: string | number; unit: string; lineTotal: number }[] };
type ProductMode = "list" | "create" | "edit";

export default function PartnerPortal() {
  const [, setLocation] = useLocation();
  const utils = trpc.useUtils();
  const sessionQuery = trpc.lahza.partner.session.useQuery();
  const [countryCode, setCountryCode] = useState(DEFAULT_COUNTRY_CODE);
  const [phone, setPhone] = useState("");
  const [password, setPassword] = useState("0000");
  const selectedCountry = countryCallingCodes.find(country => country.code === countryCode) ?? countryCallingCodes[0];
  const fullPhone = `+${selectedCountry.dialCode}${phone.replace(/\D/g, "").replace(/^0/, "")}`;
  const login = trpc.lahza.partner.login.useMutation({ onSuccess: async result => { await utils.lahza.partner.session.invalidate(); toast.success(`أهلاً بك في متجر ${result.name}`); setLocation("/partner/store"); }, onError: error => toast.error(error.message) });
  const logout = trpc.lahza.partner.logout.useMutation({ onSuccess: () => { utils.lahza.partner.session.setData(undefined, null); setLocation("/"); }, onError: error => toast.error(error.message) });

  if (sessionQuery.isLoading) return <Loading text="جارٍ فتح لوحة الشريك..." />;
  if (!sessionQuery.data) return <main dir="rtl" className="min-h-screen bg-slate-50 px-4 py-10"><section className="mx-auto max-w-md rounded-[2rem] border border-slate-200 bg-white p-6 shadow-lg"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#4a2618] text-white"><Store className="h-6 w-6" /></div><div className="mt-5 h-10 w-40 overflow-hidden rounded-xl bg-white"><img src={lahzaWordmarkUrl} alt="لحظة" className="h-10 w-full object-contain" /></div><p className="mt-2 text-sm font-bold text-red-600">بوابة الشركاء</p><h1 className="mt-1 text-2xl font-black text-[#4a2618]">دخول المتجر</h1><p className="mt-2 text-sm leading-7 text-slate-500">أدخل رقم الهاتف وكلمة المرور التي أنشأها لك المالك.</p><div className="mt-6 space-y-4"><div><Label>رقم الهاتف</Label><div className="phone-entry" dir="ltr"><select aria-label="رمز دولة الشريك" value={countryCode} onChange={event => { setCountryCode(event.target.value as typeof countryCode); setPhone(""); }} className="form-select">{countryCallingCodes.map(country => <option key={country.code} value={country.code}>+{country.dialCode} · {country.name}</option>)}</select><Input inputMode="tel" value={phone} onChange={event => setPhone(event.target.value.replace(/\D/g, "").slice(0, 15))} placeholder="رقم الهاتف" /></div></div><div><Label>كلمة مرور الشريك</Label><Input dir="ltr" type="password" value={password} onChange={event => setPassword(event.target.value)} onKeyDown={event => { if (event.key === "Enter" && password && /^\+[1-9]\d{6,14}$/.test(fullPhone)) login.mutate({ phone: fullPhone, password }); }} /></div><Button disabled={login.isPending || !/^\+[1-9]\d{6,14}$/.test(fullPhone) || !password} onClick={() => login.mutate({ phone: fullPhone, password })} className="h-11 w-full rounded-2xl bg-[#4a2618] hover:bg-[#63301b]">{login.isPending ? "جارٍ الدخول..." : "فتح لوحة المتجر"}</Button><Button variant="ghost" onClick={() => setLocation("/")} className="w-full rounded-xl text-slate-500"><ArrowRight className="h-4 w-4" /> العودة إلى لحظة</Button></div></section></main>;
  return <PartnerDashboardEnhanced partner={sessionQuery.data} onLogout={() => logout.mutate()} onHome={() => setLocation("/")} />;
}

function PartnerDashboardEnhanced({ partner, onLogout, onHome }: { partner: PartnerData; onLogout: () => void; onHome: () => void }) {
  const utils = trpc.useUtils();
  const storesQuery = trpc.lahza.partner.stores.list.useQuery();
  const productsQuery = trpc.lahza.partner.catalog.list.useQuery();
  const offersQuery = trpc.lahza.partner.offers.list.useQuery();
  const [tab, setTab] = useState<StoreTab>("products");
  const completedOrdersQuery = trpc.lahza.partner.completedOrders.useQuery(undefined, { enabled: tab === "orders", retry: false });
  const reportQuery = trpc.lahza.partner.report.useQuery(undefined, { enabled: tab === "accounts", retry: false });
  const [storeFilterCategory, setStoreFilterCategory] = useState<LahzaCategory | "all">("all");
  const [selectedStoreId, setSelectedStoreId] = useState("");
  const [productMode, setProductMode] = useState<ProductMode>("list");
  const [editingProduct, setEditingProduct] = useState<PartnerProduct | null>(null);
  const [storeOpen, setStoreOpen] = useState(partner.storeOpen);
  const [preparationMinutes, setPreparationMinutes] = useState(String(partner.preparationMinutes));
  const [partnerImage, setPartnerImage] = useState(partner.imageUrl ?? "");
  const [workHours, setWorkHours] = useState<StoreHours>(partner.workHours ?? DEFAULT_STORE_HOURS);
  const [hoursOpen, setHoursOpen] = useState(false);
  const [preview, setPreview] = useState<{ src: string; alt: string } | null>(null);
  const stores = storesQuery.data ?? partner.stores;
  const storesInCategory = stores.filter(store => storeFilterCategory === "all" || store.category === storeFilterCategory);
  const selectedStore = storesInCategory.find(store => String(store.id) === selectedStoreId) ?? storesInCategory[0] ?? null;
  const customerStoreImage = selectedStore?.imageUrl || partnerImage || null;
  useEffect(() => {
    setStoreOpen(partner.storeOpen);
    setPreparationMinutes(String(partner.preparationMinutes));
    setPartnerImage(partner.imageUrl ?? "");
    setWorkHours(partner.workHours ?? DEFAULT_STORE_HOURS);
  }, [partner.storeOpen, partner.preparationMinutes, partner.imageUrl, partner.workHours]);
  const products = selectedStore ? ((productsQuery.data ?? []) as PartnerProduct[]).filter(product => product.storeId === selectedStore.id) : [];
  const offers = selectedStore ? ((offersQuery.data ?? []) as PartnerOffer[]).filter(offer => offer.storeId === selectedStore.id) : [];
  const refreshProducts = () => { utils.lahza.partner.catalog.list.invalidate(); utils.lahza.storefront.products.invalidate(); };
  const refreshOffers = () => { utils.lahza.partner.offers.list.invalidate(); utils.lahza.intercity.offers.invalidate(); };
  const updateStoreLocation = trpc.lahza.partner.store.updateLocation.useMutation({ onSuccess: () => { utils.lahza.partner.stores.list.invalidate(); utils.lahza.partner.session.invalidate(); toast.success("تم تحديد وحفظ موقع المتجر؛ سيُستخدم لحساب المسافة والرسوم"); }, onError: error => toast.error(error.message) });
  const updateAccount = trpc.lahza.partner.store.update.useMutation({ onSuccess: () => { utils.lahza.partner.session.invalidate(); toast.success("تم حفظ بيانات الحساب والصورة"); }, onError: error => toast.error(error.message) });
  const uploadPartnerImage = trpc.lahza.partner.store.uploadImage.useMutation({ onError: error => toast.error(error.message) });
  const locateStore = () => {
    if (!selectedStore) return;
    if (!navigator.geolocation) { toast.error("لا يدعم هذا الجهاز تحديد الموقع"); return; }
    updateStoreLocation.reset();
    navigator.geolocation.getCurrentPosition(
      position => updateStoreLocation.mutate({ storeId: selectedStore.id, locationLat: position.coords.latitude, locationLng: position.coords.longitude }),
      error => toast.error(error.code === error.PERMISSION_DENIED ? "اسمح للتطبيق بالوصول إلى موقع المتجر ثم أعد المحاولة" : "تعذر تحديد موقع المتجر بدقة"),
      { enableHighAccuracy: true, timeout: 20000, maximumAge: 0 },
    );
  };
  const toggleStoreOpen = () => {
    const nextStoreOpen = !storeOpen;
    setStoreOpen(nextStoreOpen);
    updateAccount.mutate({ storeOpen: nextStoreOpen, preparationMinutes: Number(preparationMinutes), imageUrl: partnerImage || undefined }, { onError: () => setStoreOpen(storeOpen) });
  };
  const saveAccount = async () => { const uploaded = partnerImage.startsWith("data:") ? await uploadPartnerImage.mutateAsync({ dataUrl: partnerImage }) : null; updateAccount.mutate({ storeOpen, preparationMinutes: Number(preparationMinutes), imageUrl: uploaded?.imageUrl ?? partnerImage, workHours }); };
  const saveWorkHours = (nextHours: StoreHours) => { setWorkHours(nextHours); setHoursOpen(false); updateAccount.mutate({ storeOpen: true, preparationMinutes: Number(preparationMinutes), imageUrl: partnerImage || undefined, workHours: nextHours }); };
  const createProduct = trpc.lahza.partner.catalog.create.useMutation({ onSuccess: () => { refreshProducts(); toast.success("تمت إضافة المنتج"); }, onError: error => toast.error(error.message) });
  const updateProduct = trpc.lahza.partner.catalog.update.useMutation({ onSuccess: () => { refreshProducts(); toast.success("تم تحديث المنتج"); }, onError: error => toast.error(error.message) });
  const removeProduct = trpc.lahza.partner.catalog.remove.useMutation({ onSuccess: () => { refreshProducts(); toast.success("تم حذف المنتج"); }, onError: error => toast.error(error.message) });
  const uploadProductImage = trpc.lahza.partner.catalog.uploadImage.useMutation({ onError: error => toast.error(error.message) });
  const createOffer = trpc.lahza.partner.offers.create.useMutation({ onSuccess: () => { refreshOffers(); toast.success("تمت إضافة العرض إلى متجرك"); }, onError: error => toast.error(error.message) });
  const updateOffer = trpc.lahza.partner.offers.update.useMutation({ onSuccess: () => { refreshOffers(); toast.success("تم حفظ تعديل العرض؛ يلزم طلب تمييزه من جديد إن أردت ظهوره بالواجهة"); }, onError: error => toast.error(error.message) });
  const removeOffer = trpc.lahza.partner.offers.remove.useMutation({ onSuccess: () => { refreshOffers(); toast.success("أُخفي العرض من متجر العملاء"); }, onError: error => toast.error(error.message) });
  const uploadOfferImage = trpc.lahza.partner.offers.uploadImage.useMutation({ onError: error => toast.error(error.message) });
  const requestFeaturedOffer = trpc.lahza.partner.offers.requestFeatured.useMutation({ onSuccess: () => { refreshOffers(); toast.success("تم إرسال العرض المميز للمالك للمراجعة"); }, onError: error => toast.error(error.message) });
  const uploadProductImages = async (dataUrls: string[] | undefined) => !selectedStore ? [] : Promise.all((dataUrls ?? []).map(dataUrl => uploadProductImage.mutateAsync({ storeId: selectedStore.id, dataUrl }).then(result => result.imageUrl)));
  const uploadClothingVariants = async (variants: ProductDraft["variantDataUrls"]) => Promise.all(variants.map(async variant => ({ size: variant.size, color: variant.color, imageUrls: await uploadProductImages(variant.dataUrls) })));
  const saveNewProduct = async (input: ProductDraft) => { if (!selectedStore) return; const imageUrls = await uploadProductImages(input.dataUrls); const clothingVariantImages = await uploadClothingVariants(input.variantDataUrls); await createProduct.mutateAsync({ name: input.name, category: selectedStore.category, storeId: selectedStore.id, unit: input.unit, price: input.price, available: true, imageUrl: imageUrls[0] ?? "", imageUrls, clothingSizes: input.clothingSizes, clothingColors: input.clothingColors, clothingVariantImages }); setProductMode("list"); };
  const saveEditedProduct = async (input: ProductDraft) => { if (!selectedStore || !editingProduct) return; const newImageUrls = await uploadProductImages(input.dataUrls); const oldImageUrls = input.dataUrls?.length ? [] : parseProductImages(editingProduct); const imageUrls = [...oldImageUrls, ...newImageUrls]; const existingVariants = parseVariantImages(editingProduct.clothingVariantImages); const variantsByKey = new Map(existingVariants.map(variant => [`${variant.size}::${variant.color}`, variant])); for (const variant of await uploadClothingVariants(input.variantDataUrls)) variantsByKey.set(`${variant.size}::${variant.color}`, variant); const clothingVariantImages = Array.from(variantsByKey.values()).filter(variant => input.clothingSizes.includes(variant.size) && input.clothingColors.includes(variant.color)); await updateProduct.mutateAsync({ id: editingProduct.id, name: input.name, category: selectedStore.category, storeId: selectedStore.id, unit: input.unit, price: input.price, available: editingProduct.available, imageUrl: imageUrls[0] ?? "", imageUrls, clothingSizes: input.clothingSizes, clothingColors: input.clothingColors, clothingVariantImages }); setEditingProduct(null); setProductMode("list"); };
  const addOffer = async (input: { catalogItemId: number; text: string; durationDays: number; offerPrice: number; dataUrl?: string }) => { if (!selectedStore) return 0; const image = input.dataUrl ? await uploadOfferImage.mutateAsync({ storeId: selectedStore.id, dataUrl: input.dataUrl }) : null; const created = await createOffer.mutateAsync({ storeId: selectedStore.id, catalogItemId: input.catalogItemId, text: input.text, durationDays: input.durationDays, offerPrice: input.offerPrice, imageUrl: image?.imageUrl ?? "", imageStorageKey: image?.imageStorageKey ?? "", active: true }); return created.id; };
  const storeCategoryTitle = (store: AssignedStore) => store.categoryTitle ?? categoryMeta[store.category].title;
  if (storesQuery.isLoading) return <Loading text="جارٍ تحميل المتجر..." />;
  if (!stores.length || !selectedStore) return <main dir="rtl" className="min-h-screen bg-slate-50 px-4 py-8"><EmptyStores /></main>;
  return (
    <main dir="rtl" className="min-h-screen bg-slate-50 text-slate-950">
      <header className="border-b border-slate-200 bg-white">
        <div className="mx-auto flex w-full max-w-5xl flex-wrap items-center justify-between gap-3 px-4 py-4">
          <div><p className="text-xs font-bold text-red-600">لحظة للشركاء</p><div className="mt-1 h-8 w-40"><img src={lahzaWordmarkUrl} alt="لحظة" className="h-full w-full object-contain" /></div></div>
          <div className="flex items-center gap-2"><Button variant="outline" onClick={onHome} className="rounded-xl border-rose-200 bg-rose-50 text-[#63301b]"><ArrowRight className="h-4 w-4" /> الصفحة الرئيسية</Button><Button variant="outline" onClick={onLogout} className="rounded-xl text-slate-600"><LogOut className="h-4 w-4" /> خروج</Button></div>
        </div>
      </header>
      <section className="mx-auto grid w-full max-w-5xl gap-5 px-4 py-6">
        {stores.length > 1 ? <div className="grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 sm:grid-cols-2"><div><Label>القسم</Label><select value={storeFilterCategory} onChange={event => { setStoreFilterCategory(event.target.value as LahzaCategory | "all"); setSelectedStoreId(""); setProductMode("list"); setEditingProduct(null); }} className="form-select mt-1"><option value="all">كل الأقسام</option>{Array.from(new Set(stores.map(store => store.category))).map(category => <option key={category} value={category}>{categoryMeta[category].title}</option>)}</select></div><div><Label>المتجر</Label><select value={selectedStore.id} onChange={event => { setSelectedStoreId(event.target.value); setProductMode("list"); setEditingProduct(null); }} className="form-select mt-1">{storesInCategory.map(store => <option key={store.id} value={store.id}>{store.name}</option>)}</select></div></div> : null}
        <section className="overflow-hidden rounded-3xl bg-gradient-to-l from-[#4a2618] via-[#63301b] to-red-600 text-white shadow-lg">
          <div className="relative h-52 w-full bg-black/15 sm:h-64">{customerStoreImage ? <img src={customerStoreImage} alt={`صورة متجر ${selectedStore.name}`} className="h-full w-full object-cover" /> : <div className="grid h-full place-items-center"><Store className="h-16 w-16 text-white/80" /></div>}<div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/75 to-transparent px-5 pb-5 pt-14"><p className="text-sm font-bold text-rose-100">بوابة الشريك · {storeCategoryTitle(selectedStore)}</p><h1 className="mt-1 text-3xl font-black">{selectedStore.name}</h1></div></div>
        </section>
        <nav aria-label="أقسام بوابة الشريك" className="grid grid-cols-2 gap-3 sm:grid-cols-4">
          <TabButton active={tab === "products"} onClick={() => { setTab("products"); setProductMode("list"); }} icon={<PackagePlus className="h-5 w-5" />}>المنتجات</TabButton>
          <TabButton active={tab === "offers"} onClick={() => setTab("offers")} icon={<BadgePercent className="h-5 w-5" />}>العروض</TabButton>
          <TabButton active={tab === "orders"} onClick={() => setTab("orders")} icon={<PackageCheck className="h-5 w-5" />}>الطلبات المكتملة</TabButton>
          <TabButton active={tab === "accounts"} onClick={() => setTab("accounts")} icon={<WalletCards className="h-5 w-5" />}>الحسابات</TabButton>
        </nav>
        {tab === "products" ? <ProductsPanel store={selectedStore} products={products} mode={productMode} editingProduct={editingProduct} saving={createProduct.isPending || updateProduct.isPending || removeProduct.isPending || uploadProductImage.isPending} onNew={() => { setEditingProduct(null); setProductMode("create"); }} onCancel={() => { setEditingProduct(null); setProductMode("list"); }} onEdit={product => { setEditingProduct(product); setProductMode("edit"); }} onCreate={saveNewProduct} onUpdate={saveEditedProduct} onToggle={product => updateProduct.mutate({ id: product.id, name: product.name, category: selectedStore.category, storeId: selectedStore.id, unit: product.unit, price: toNewSyp(product.unitPrice), available: !product.available, imageUrl: product.imageUrl ?? "", imageUrls: parseProductImages(product), clothingSizes: parseStringArray(product.clothingSizes), clothingColors: parseStringArray(product.clothingColors), clothingVariantImages: parseVariantImages(product.clothingVariantImages) })} onRemove={product => { if (confirm(`حذف ${product.name}؟`)) removeProduct.mutate({ id: product.id }); }} onPreview={(src, alt) => setPreview({ src, alt })} /> : null}
        {tab === "offers" ? <><OffersPanel featuredOnly offers={offers} products={products} store={selectedStore} creating={createOffer.isPending || uploadOfferImage.isPending || requestFeaturedOffer.isPending} saving={updateOffer.isPending} deleting={removeOffer.isPending} onCreate={async input => { const id = await addOffer(input); await requestFeaturedOffer.mutateAsync({ id, storeId: selectedStore.id }); refreshOffers(); toast.success("تم إنشاء العرض المميز وإرساله للمالك للمراجعة"); }} onUpdate={input => updateOffer.mutate(input)} onRemove={id => { if (confirm("حذف هذا العرض؟")) removeOffer.mutate({ id, storeId: selectedStore.id }); }} onPreview={(src, alt) => setPreview({ src, alt })} /><FeaturedOffersPanel offers={offers} submitting={requestFeaturedOffer.isPending} onRequest={offer => requestFeaturedOffer.mutate({ id: offer.id, storeId: selectedStore.id })} /></> : null}
        {tab === "orders" ? <CompletedOrdersPanel orders={(completedOrdersQuery.data ?? []) as PartnerCompletedOrder[]} loading={completedOrdersQuery.isLoading} /> : null}
        {tab === "accounts" ? <section className="space-y-5">
          <section className="rounded-3xl border border-rose-100 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm font-bold text-[#63301b]">إعدادات المتجر</p><p className="mt-1 text-xs text-slate-500">حالة العمل ومواعيده وموقعه وصورته.</p></div><button onClick={toggleStoreOpen} disabled={updateAccount.isPending} className={`rounded-full px-4 py-2 text-sm font-bold ${storeOpen ? "bg-emerald-600 text-white" : "bg-slate-400 text-white"}`}>{storeOpen ? "المتجر مفتوح" : "المتجر مغلق"}</button><Button type="button" variant="outline" onClick={locateStore} disabled={updateStoreLocation.isPending} className="rounded-full border-rose-200 bg-white text-[#63301b]"><LocateFixed className="h-4 w-4" />{updateStoreLocation.isPending ? "جارٍ تحديد الموقع..." : "تحديد موقع المتجر"}</Button><Button type="button" variant="outline" onClick={() => setHoursOpen(true)} className="rounded-full border-rose-200 bg-white text-[#63301b]"><Store className="h-4 w-4" /> ساعات العمل</Button></div><div className="mt-3 rounded-2xl border border-rose-100 bg-rose-50/60 px-4 py-3 text-xs text-slate-600"><strong className="text-[#63301b]">الموقع المرجعي:</strong> {selectedStore.locationLat && selectedStore.locationLng ? `${(selectedStore.locationLat / 1000000).toFixed(6)}, ${(selectedStore.locationLng / 1000000).toFixed(6)}` : "لم يُحدد بعد"} <span className="text-slate-400">(العرض، الطول)</span></div><div className="mt-4 flex flex-wrap items-end gap-3"><div><Label>وقت التجهيز بالدقائق</Label><Input inputMode="numeric" value={preparationMinutes} onChange={event => setPreparationMinutes(event.target.value.replace(/\D/g, ""))} className="mt-1 w-48 bg-white" /></div><div><Label>صورة المتجر الظاهرة للزبائن</Label><label className="mt-1 inline-flex cursor-pointer items-center gap-2 rounded-xl border border-orange-200 bg-white px-3 py-2 text-xs font-bold text-[#63301b]"><ImagePlus className="h-4 w-4" /> رفع صورة<input type="file" accept="image/png,image/jpeg,image/webp" className="sr-only" onChange={async event => { const file = event.target.files?.[0]; if (!file) return; try { setPartnerImage(await readImageFile(file)); } catch { toast.error("تعذر قراءة الصورة"); } }} /></label>{partnerImage ? <img src={partnerImage} alt="صورة المتجر" className="mt-1 h-10 w-10 rounded-lg object-cover" /> : null}</div><Button disabled={updateAccount.isPending || uploadPartnerImage.isPending || !preparationMinutes} onClick={saveAccount} className="rounded-xl bg-[#4a2618] hover:bg-[#63301b]">حفظ الإعدادات</Button></div></section>
          <section className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-bold text-red-600">آخر ٧ أيام</p><h2 className="text-lg font-black text-[#4a2618]">ملخص الحسابات والأداء</h2></div><Button type="button" variant="outline" size="sm" onClick={() => void reportQuery.refetch()}>تحديث</Button></div>{reportQuery.isLoading ? <Loading text="جارٍ إعداد ملخص الحسابات..." /> : reportQuery.data ? <><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><AccountMetric label="قيمة الطلبات غير الملغاة" value={formatSyp(reportQuery.data.current.sales)} /><AccountMetric label="طلبات مكتملة" value={String(reportQuery.data.current.completed)} /><AccountMetric label="كل الطلبات" value={String(reportQuery.data.current.orders)} /><AccountMetric label="زيارات المتجر" value={String(reportQuery.data.visits)} /></div><p className="mt-3 text-xs leading-6 text-slate-500">القيمة إجمالي الطلبات غير الملغاة خلال الأيام السبعة، وليست كشف تسوية أو مستحقات مالية.</p>{reportQuery.data.current.topProducts.length ? <div className="mt-4 rounded-2xl bg-slate-50 p-4"><h3 className="font-black text-[#4a2618]">الأكثر مبيعاً</h3><div className="mt-2 space-y-2">{reportQuery.data.current.topProducts.slice(0, 5).map((item, index) => <div key={`${item.name}-${index}`} className="flex justify-between gap-3 text-sm"><span>{item.name}</span><strong>{item.quantity}</strong></div>)}</div></div> : null}</> : <p className="mt-4 text-sm text-slate-500">تعذر تحميل البيانات الآن. أعد المحاولة.</p>}</section>
        </section> : null}
      </section>
      <ImagePreview preview={preview} onClose={() => setPreview(null)} />
      <StoreHoursDialog open={hoursOpen} onOpenChange={setHoursOpen} value={workHours} saving={updateAccount.isPending} onSave={saveWorkHours} />
    </main>
  );
}

type ProductDraft = { name: string; unit: string; price: number; stockQuantity: number; stockInitialQuantity?: number; stockAlertPercent: number; dataUrls?: string[]; clothingSizes: string[]; clothingColors: string[]; variantDataUrls: Array<{ size: string; color: string; dataUrls: string[] }> };
function parseStringArray(value?: string | null) {
  try {
    const parsed: unknown = JSON.parse(value || "[]");
    return Array.isArray(parsed) ? parsed.filter((item): item is string => typeof item === "string") : [];
  } catch {
    return [];
  }
}

function parseProductImages(product: PartnerProduct) {
  const images = parseStringArray(product.imageUrls);
  return images.length ? images : product.imageUrl ? [product.imageUrl] : [];
}

function parseVariantImages(value?: string | null) {
  try {
    const parsed: unknown = JSON.parse(value || "[]");
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((item): item is { size: string; color: string; imageUrls: string[] } => Boolean(item && typeof item === "object" && typeof item.size === "string" && typeof item.color === "string" && Array.isArray(item.imageUrls) && item.imageUrls.every((url: unknown) => typeof url === "string")));
  } catch {
    return [];
  }
}

function AccountMetric({ label, value }: { label: string; value: string }) {
  return <div className="rounded-2xl border border-slate-100 bg-slate-50 p-4"><span className="block text-xs font-bold text-slate-500">{label}</span><strong className="mt-2 block text-xl font-black text-[#4a2618]">{value}</strong></div>;
}

function CompletedOrdersPanel({ orders, loading }: { orders: PartnerCompletedOrder[]; loading: boolean }) {
  if (loading) return <Loading text="جارٍ تحميل الطلبات المكتملة..." />;
  return <section className="space-y-4"><div className="rounded-3xl border border-slate-200 bg-white p-5"><p className="text-xs font-bold text-red-600">سجل المتجر</p><h2 className="mt-1 text-xl font-black text-[#4a2618]">الطلبات المكتملة</h2><p className="mt-1 text-sm text-slate-500">يعرض المنتجات التابعة لمتاجرك فقط، مع قيمة البنود وتاريخ إتمام الطلب.</p></div>{orders.length ? <div className="space-y-3">{orders.map(order => <article key={order.orderId} className="rounded-2xl border border-emerald-100 bg-white p-4 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-2"><strong className="text-[#4a2618]">طلب مكتمل #{order.orderId}</strong><span className="text-xs text-slate-500">{new Date(order.createdAt).toLocaleString("ar-SY")}</span></div><div className="mt-3 space-y-2">{order.items.map((item, index) => <div key={`${order.orderId}-${index}`} className="flex flex-wrap justify-between gap-2 rounded-xl bg-slate-50 px-3 py-2 text-sm"><span>{item.name} · {item.quantity} {item.unit}</span><strong>{formatSyp(item.lineTotal)}</strong></div>)}</div><div className="mt-3 flex justify-between border-t border-slate-100 pt-3 text-sm"><span className="font-bold text-slate-600">مجموع منتجات المتجر في الطلب</span><strong className="text-emerald-700">{formatSyp(order.itemTotal)}</strong></div></article>)}</div> : <div className="rounded-3xl border border-dashed border-slate-200 bg-white p-8 text-center"><PackageCheck className="mx-auto h-8 w-8 text-slate-400" /><strong className="mt-3 block text-[#4a2618]">لا توجد طلبات مكتملة بعد</strong><p className="mt-2 text-sm text-slate-500">ستظهر هنا الطلبات بعد إتمامها.</p></div>}</section>;
}

function ProductsPanel({ store, products, mode, editingProduct, saving, onNew, onCancel, onEdit, onCreate, onUpdate, onToggle, onRemove, onPreview }: { store: AssignedStore; products: PartnerProduct[]; mode: ProductMode; editingProduct: PartnerProduct | null; saving: boolean; onNew: () => void; onCancel: () => void; onEdit: (product: PartnerProduct) => void; onCreate: (input: ProductDraft) => Promise<void>; onUpdate: (input: ProductDraft) => Promise<void>; onToggle: (product: PartnerProduct) => void; onRemove: (product: PartnerProduct) => void; onPreview: (src: string, alt: string) => void }) {
  return <section className="space-y-5">{mode === "list" ? <><div className="flex flex-wrap items-center justify-between gap-3 rounded-3xl border border-slate-200 bg-white p-5"><div><h2 className="text-lg font-black text-[#4a2618]">منتجات {store.name}</h2><p className="mt-1 text-sm text-slate-500">قائمة واضحة؛ اضغط تعديل المنتج لتغيير بياناته أو حالته.</p></div><Button onClick={onNew} className="rounded-xl bg-red-600 hover:bg-red-700"><Plus className="h-4 w-4" /> إضافة منتج جديد</Button></div>{products.length ? <div className="grid grid-cols-1 gap-3">{products.map(product => <article key={product.id} className="flex flex-col gap-3 rounded-2xl border border-slate-200 bg-white p-3 shadow-sm sm:flex-row sm:items-center"><ImageThumbnail src={product.imageUrl} alt={`صورة ${product.name}`} onPreview={onPreview} /><div className="min-w-0 flex-1"><strong className="block truncate text-base text-[#4a2618]">{product.name}</strong><span className="mt-1 block text-xs text-slate-500">{product.unit} · {formatSyp(product.unitPrice)} · {product.available ? "متاح" : "موقوف"}</span><Button size="sm" variant="outline" onClick={() => onEdit(product)} className="mt-3 rounded-lg border-rose-100 bg-rose-50 text-[#63301b]"><Pencil className="h-3.5 w-3.5" /> تعديل منتج</Button></div></article>)}</div> : <div className="rounded-3xl border border-dashed border-slate-200 bg-white p-8 text-center"><PackagePlus className="mx-auto h-8 w-8 text-slate-400" /><strong className="mt-3 block text-[#4a2618]">لا توجد منتجات بعد</strong><p className="mt-2 text-sm text-slate-500">ابدأ بإضافة أول منتج إلى متجر {store.name}.</p><Button onClick={onNew} className="mt-4 rounded-xl bg-red-600 hover:bg-red-700"><Plus className="h-4 w-4" /> إضافة منتج جديد</Button></div>}</> : <ProductForm title={mode === "create" ? "إضافة منتج جديد" : `تعديل ${editingProduct?.name ?? "المنتج"}`} product={mode === "edit" ? editingProduct : null} category={store.category} saving={saving} onCancel={onCancel} onSave={mode === "create" ? onCreate : onUpdate} onToggle={mode === "edit" && editingProduct ? () => onToggle(editingProduct) : undefined} onRemove={mode === "edit" && editingProduct ? () => onRemove(editingProduct) : undefined} onPreview={onPreview} />}</section>;
}

function ProductForm({ title, product, category, saving, onCancel, onSave, onToggle, onRemove, onPreview }: { title: string; product: PartnerProduct | null; category: LahzaCategory; saving: boolean; onCancel: () => void; onSave: (input: ProductDraft) => Promise<void>; onToggle?: () => void; onRemove?: () => void; onPreview: (src: string, alt: string) => void }) {
  const [name, setName] = useState(product?.name ?? "");
  const [price, setPrice] = useState(product ? String(toNewSyp(product.unitPrice)) : "");
  const [unit, setUnit] = useState(product?.unit ?? productUnitsForCategory(category)[0]);
  const [stockQuantity, setStockQuantity] = useState(String(product?.stockQuantity ?? 0));
  const [stockInitialQuantity, setStockInitialQuantity] = useState(String(product?.stockInitialQuantity ?? product?.stockQuantity ?? 0));
  const [stockAlertPercent, setStockAlertPercent] = useState(String(product?.stockAlertPercent ?? 20));
  const [dataUrls, setDataUrls] = useState<string[]>([]);
  const parseList = (value?: string | null) => { try { const parsed = JSON.parse(value || "[]"); return Array.isArray(parsed) ? parsed.filter(item => typeof item === "string") : []; } catch { return []; } };
  const [sizes, setSizes] = useState<string[]>(parseList(product?.clothingSizes));
  const [colors, setColors] = useState<string[]>(parseList(product?.clothingColors));
  const [variantDataUrls, setVariantDataUrls] = useState<Array<{ size: string; color: string; dataUrls: string[] }>>([]);
  const sizeOptions = ["XS", "S", "M", "L", "XL", "XXL", "3XL", "4XL"];
  const chooseImages = async (files: FileList | null) => { if (!files) return; const selected = Array.from(files).slice(0, 10); if (selected.some(file => !/^image\/(png|jpeg|webp)$/.test(file.type) || file.size > 5 * 1024 * 1024)) { toast.error("اختر صور PNG أو JPG أو WEBP، وكل صورة أقل من 5 ميغابايت"); return; } setDataUrls(await Promise.all(selected.map(readImageFile))); };
  const addVariantImages = async (size: string, color: string, files: FileList | null) => { if (!files || !size || !color) return; const selected = Array.from(files).slice(0, 10); if (selected.some(file => !/^image\/(png|jpeg|webp)$/.test(file.type) || file.size > 5 * 1024 * 1024)) { toast.error("اختر صوراً صحيحة بحجم مناسب"); return; } const images = await Promise.all(selected.map(readImageFile)); setVariantDataUrls(current => [...current.filter(item => item.size !== size || item.color !== color), { size, color, dataUrls: images }]); };
  const oldImages = parseList(product?.imageUrls); const imageSrcs = dataUrls.length ? dataUrls : oldImages.length ? oldImages : (product?.imageUrl ? [product.imageUrl] : []);
  const colorText = colors.join(", ");
  const inventoryFields = <div className="mt-4 grid gap-4 rounded-2xl border border-amber-100 bg-amber-50 p-4"><div><Label>الكمية الحالية ({unit})</Label><Input inputMode="numeric" value={stockQuantity} onChange={event => setStockQuantity(event.target.value.replace(/\D/g, ""))} /></div><div><Label>كمية بداية المخزون</Label><Input inputMode="numeric" value={stockInitialQuantity} onChange={event => setStockInitialQuantity(event.target.value.replace(/\D/g, ""))} /></div><div><Label>نسبة التنبيه %</Label><Input inputMode="numeric" value={stockAlertPercent} onChange={event => setStockAlertPercent(event.target.value.replace(/\D/g, ""))} /><small className="mt-1 block text-xs text-slate-500">تنبيه داخلي لا يظهر للعميل.</small></div></div>;
  return <section className="rounded-3xl border border-slate-200 bg-white p-5"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-bold text-red-600">إدارة المنتجات</p><h2 className="mt-1 text-xl font-black text-[#4a2618]">{title}</h2></div><Button variant="ghost" onClick={onCancel} className="rounded-xl text-slate-500"><X className="h-4 w-4" /> إغلاق</Button></div><div className="mt-5 grid gap-4 md:grid-cols-2"><div><Label>اسم المنتج</Label><Input value={name} onChange={event => setName(event.target.value)} className="mt-1" /></div><div><Label>الوحدة</Label><select value={unit} onChange={event => setUnit(event.target.value)} className="form-select mt-1">{productUnitsForCategory(category, unit).map(option => <option key={option} value={option}>{option}</option>)}</select></div><div><Label>السعر (ل.س)</Label><Input inputMode="numeric" value={price} onChange={event => setPrice(event.target.value.replace(/\D/g, ""))} className="mt-1" /></div></div>{inventoryFields}<div className="mt-4 rounded-2xl border border-dashed border-slate-200 bg-slate-50 p-3"><Label className="flex items-center gap-2"><ImageIcon className="h-4 w-4 text-red-600" /> صور المنتج <span className="text-slate-400">(حتى 10 صور)</span></Label><div className="mt-3 flex flex-wrap items-center gap-3"><label className="inline-flex cursor-pointer items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-bold text-[#4a2618]"><ImagePlus className="h-4 w-4" /> اختيار صور<input type="file" multiple className="sr-only" accept="image/png,image/jpeg,image/webp" onChange={event => { void chooseImages(event.target.files); }} /></label>{imageSrcs.map((src, index) => <ImageThumbnail key={`${src}-${index}`} src={src} alt={`صورة ${name || "المنتج"} ${index + 1}`} onPreview={onPreview} />)}</div>{dataUrls.length ? <button type="button" onClick={() => setDataUrls([])} className="mt-2 text-xs font-bold text-red-600">إلغاء الصور الجديدة</button> : null}</div>{category === "clothing" ? <ClothingProductFields sizes={sizes} onSizesChange={setSizes} colors={colors} onColorsChange={setColors} variantDataUrls={variantDataUrls} onAddVariantImages={addVariantImages} /> : null}<div className="mt-5 flex flex-wrap gap-2"><Button disabled={saving || !name.trim() || !price} onClick={() => onSave({ name: name.trim(), unit, price: Number(price), stockQuantity: Number(stockQuantity), stockInitialQuantity: Number(stockInitialQuantity), stockAlertPercent: Number(stockAlertPercent) || 20, dataUrls, clothingSizes: category === "clothing" ? sizes : [], clothingColors: category === "clothing" ? colors : [], variantDataUrls: category === "clothing" ? variantDataUrls : [] })} className="rounded-xl bg-[#4a2618] hover:bg-[#63301b]">{saving ? "جارٍ الحفظ..." : "حفظ المنتج"}</Button>{onToggle && product ? <Button disabled={saving} variant="outline" onClick={onToggle} className="rounded-xl border-amber-200 bg-amber-50 text-amber-800">{product.available ? "إيقاف المنتج" : "تفعيل المنتج"}</Button> : null}{onRemove ? <Button disabled={saving} variant="outline" onClick={onRemove} className="rounded-xl border-red-100 bg-red-50 text-red-700"><Trash2 className="h-4 w-4" /> حذف المنتج</Button> : null}</div></section>;
}
function OffersPanel({ featuredOnly = false, offers, products, store, creating, saving, deleting, onCreate, onUpdate, onRemove, onPreview }: { featuredOnly?: boolean; offers: PartnerOffer[]; products: PartnerProduct[]; store: AssignedStore; creating: boolean; saving: boolean; deleting: boolean; onCreate: (input: { catalogItemId: number; text: string; durationDays: number; offerPrice: number; dataUrl?: string }) => Promise<void>; onUpdate: (input: { id: number; storeId: number; catalogItemId: number; text: string; imageUrl: string; imageStorageKey: string; durationDays: number; offerPrice: number; active: boolean }) => void; onRemove: (id: number) => void; onPreview: (src: string, alt: string) => void }) {
  const [text, setText] = useState("");
  const [catalogItemId, setCatalogItemId] = useState("");
  const [durationDays, setDurationDays] = useState("3");
  const [offerPrice, setOfferPrice] = useState("");
  const [dataUrl, setDataUrl] = useState("");
  const availableProducts = products.filter(product => product.available);
  const selectedProduct = availableProducts.find(product => String(product.id) === catalogItemId) ?? null;
  const originalPriceNew = selectedProduct ? toNewSyp(selectedProduct.unitPrice) : 0;
  const offerPriceNew = Number(offerPrice);
  const calculatedDiscount = originalPriceNew > 0 && offerPriceNew > 0 ? Math.round((originalPriceNew - offerPriceNew) * 100 / originalPriceNew) : 0;
  const validDuration = Number(durationDays) >= 1 && Number(durationDays) <= 365;
  const validOfferPrice = Number.isInteger(offerPriceNew) && offerPriceNew > 0 && offerPriceNew < originalPriceNew && calculatedDiscount >= 1 && calculatedDiscount <= 90;
  const chooseImage = (file?: File) => {
    if (!file) return;
    if (!/^image\/(png|jpeg|webp)$/.test(file.type) || file.size > 5 * 1024 * 1024) { toast.error("اختر صورة PNG أو JPG أو WEBP بحجم لا يتجاوز 5 ميغابايت"); return; }
    const reader = new FileReader();
    reader.onload = () => setDataUrl(String(reader.result ?? ""));
    reader.readAsDataURL(file);
  };
  return <section className="grid gap-5 lg:grid-cols-2"><section className="rounded-3xl border border-red-100 bg-white p-5"><div className="flex items-center gap-2"><BadgePercent className="h-5 w-5 text-red-600" /><div><h2 className="text-lg font-black text-[#4a2618]">{featuredOnly ? "إنشاء عرض مميز جديد" : "صمّم عرضاً مميزاً"}</h2><p className="mt-1 text-xs leading-6 text-slate-500">اختر المنتج وأدخل سعر العرض الجديد؛ يحسب لحظة نسبة الخصم تلقائياً.</p></div></div><div className="mt-5 space-y-3"><div><Label>عنوان العرض</Label><Textarea value={text} onChange={event => setText(event.target.value)} placeholder="مثال: عرض نهاية الأسبوع على علبة المعمول" /></div><div><Label>صنف العرض</Label><select value={catalogItemId} onChange={event => { setCatalogItemId(event.target.value); setOfferPrice(""); }} className="form-select mt-1"><option value="">اختر صنفاً من منتجات {store.name}</option>{availableProducts.map(product => <option key={product.id} value={product.id}>{product.name} · {formatSyp(product.unitPrice)}</option>)}</select>{!availableProducts.length ? <p className="mt-1 text-xs text-red-600">أضف منتجاً متاحاً إلى المتجر أولاً.</p> : null}</div><div className="grid grid-cols-2 gap-3"><div><Label>سعر العرض الجديد (ل.س)</Label><Input disabled={!selectedProduct} inputMode="numeric" value={offerPrice} onChange={event => setOfferPrice(event.target.value.replace(/\D/g, ""))} placeholder={selectedProduct ? "أدخل سعر العرض" : "اختر المنتج أولاً"} className="mt-1" /><p className="mt-1 text-xs text-slate-500">سعر المنتج: {selectedProduct ? formatSyp(selectedProduct.unitPrice) : "—"}</p></div><div><Label>مدة العرض بالأيام</Label><Input inputMode="numeric" value={durationDays} onChange={event => setDurationDays(event.target.value.replace(/\D/g, ""))} className="mt-1" /><p className="mt-1 text-xs text-slate-500">من يوم إلى 365 يوماً.</p></div></div><div className={`rounded-xl px-3 py-2 text-xs font-bold ${validOfferPrice ? "bg-emerald-50 text-emerald-800" : offerPrice ? "bg-red-50 text-red-700" : "bg-rose-50 text-[#63301b]"}`}>{validOfferPrice ? <>نسبة الخصم المحسوبة: <strong>{calculatedDiscount}%</strong> · سعر العرض صالح</> : offerPrice ? "يجب أن يكون سعر العرض أقل من سعر المنتج وأن يحقق خصماً بين 1% و90%." : "أدخل سعر العرض الجديد ليظهر مقدار الخصم تلقائياً."}</div><div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50 p-3"><Label className="flex items-center gap-2"><ImageIcon className="h-4 w-4 text-red-600" /> صورة إضافية <span className="text-slate-400">(اختيارية)</span></Label><p className="mt-1 text-xs leading-5 text-slate-500">يستخدم القالب صورة المنتج تلقائياً. أضف صورة فقط إذا أردت خلفية أو لقطة إضافية.</p><div className="mt-3 flex flex-wrap items-center gap-3"><label className="inline-flex cursor-pointer items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-bold text-[#4a2618]"><ImagePlus className="h-4 w-4" /> اختيار صورة<input type="file" className="sr-only" accept="image/png,image/jpeg,image/webp" onChange={event => chooseImage(event.target.files?.[0])} /></label>{dataUrl ? <><ImageThumbnail src={dataUrl} alt="صورة إضافية للعرض" onPreview={onPreview} /><button type="button" onClick={() => setDataUrl("")} className="text-xs font-bold text-red-600">إزالة الصورة</button></> : null}</div></div><Button disabled={creating || text.trim().length < 3 || !catalogItemId || !validDuration || !validOfferPrice} onClick={async () => { await onCreate({ catalogItemId: Number(catalogItemId), text: text.trim(), durationDays: Number(durationDays), offerPrice: offerPriceNew, dataUrl: dataUrl || undefined }); setText(""); setCatalogItemId(""); setOfferPrice(""); setDataUrl(""); }} className="w-full rounded-xl bg-red-600 hover:bg-red-700">{creating ? "جارٍ إنشاء العرض..." : featuredOnly ? "إنشاء وإرسال العرض المميز" : "حفظ بطاقة العرض"}</Button></div></section><section className="rounded-3xl border border-rose-100 bg-white p-5"><div className="flex items-center gap-2"><BadgePercent className="h-5 w-5 text-red-600" /><div><h2 className="text-lg font-black text-[#4a2618]">معاينة بطاقة لحظة</h2><p className="mt-1 text-xs text-slate-500">هذه هي البطاقة التي يراجعها المالك قبل النشر.</p></div></div><div className="mt-4"><OfferArtworkPreview product={selectedProduct} storeName={store.name} title={text || "عنوان العرض"} offerPrice={validOfferPrice ? toLegacySyp(offerPriceNew) : undefined} customImage={dataUrl || undefined} /></div></section>{!featuredOnly ? <section className="lg:col-span-2 rounded-3xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><BadgePercent className="h-5 w-5 text-red-600" /><h2 className="text-lg font-black text-[#4a2618]">العروض المضافة</h2></div>{offers.length ? <div className="mt-4 grid gap-3 lg:grid-cols-2">{offers.map(offer => <OfferEditor key={offer.id} offer={offer} products={availableProducts} storeId={store.id} saving={saving} deleting={deleting} onUpdate={onUpdate} onRemove={onRemove} onPreview={onPreview} />)}</div> : <p className="mt-4 rounded-2xl bg-slate-50 p-4 text-sm text-slate-500">لا توجد عروض مضافة في هذا المتجر بعد.</p>}</section> : null}</section>;
}

function OfferEditor({ offer, products, storeId, saving, deleting, onUpdate, onRemove, onPreview }: { offer: PartnerOffer; products: PartnerProduct[]; storeId: number; saving: boolean; deleting: boolean; onUpdate: (input: { id: number; storeId: number; catalogItemId: number; text: string; imageUrl: string; imageStorageKey: string; durationDays: number; offerPrice: number; active: boolean }) => void; onRemove: (id: number) => void; onPreview: (src: string, alt: string) => void }) {
  const [text, setText] = useState(offer.text);
  const [catalogItemId, setCatalogItemId] = useState(offer.catalogItemId ? String(offer.catalogItemId) : "");
  const [durationDays, setDurationDays] = useState(String(offer.durationDays ?? 3));
  const [offerPrice, setOfferPrice] = useState(String(toNewSyp(offer.offerPrice)));
  const [active, setActive] = useState(offer.active);
  const selectedProduct = products.find(product => String(product.id) === catalogItemId) ?? null;
  const originalPriceNew = selectedProduct ? toNewSyp(selectedProduct.unitPrice) : 0;
  const offerPriceNew = Number(offerPrice);
  const calculatedDiscount = originalPriceNew > 0 && offerPriceNew > 0 ? Math.round((originalPriceNew - offerPriceNew) * 100 / originalPriceNew) : 0;
  const validOfferPrice = Number.isInteger(offerPriceNew) && offerPriceNew > 0 && offerPriceNew < originalPriceNew && calculatedDiscount >= 1 && calculatedDiscount <= 90;
  const expiresAt = offer.expiresAt ? new Date(offer.expiresAt) : null;
  const expired = !offer.active || Boolean(expiresAt && expiresAt.getTime() <= Date.now());
  const daysRemaining = offerDaysRemaining(offer.expiresAt);
  return <article className="rounded-2xl border border-slate-200 p-3"><OfferArtworkPreview product={selectedProduct} storeName="لحظة" title={text || "عنوان العرض"} offerPrice={validOfferPrice ? toLegacySyp(offerPriceNew) : offer.offerPrice} customImage={offer.imageUrl || undefined} compact /><div className="mt-3 grid gap-3 sm:grid-cols-2"><div><Label>وصف العرض</Label><Textarea value={text} onChange={event => setText(event.target.value)} className="mt-1 min-h-20" /></div><div className="grid content-start gap-3"><div><Label>صنف العرض</Label><select value={catalogItemId} onChange={event => setCatalogItemId(event.target.value)} className="form-select mt-1"><option value="">اختر صنف العرض</option>{products.map(product => <option key={product.id} value={product.id}>{product.name} · {formatSyp(product.unitPrice)}</option>)}</select></div><div className="grid grid-cols-2 gap-2"><div><Label>سعر العرض</Label><Input inputMode="numeric" value={offerPrice} onChange={event => setOfferPrice(event.target.value.replace(/\D/g, ""))} className="mt-1 h-9" /><p className="mt-1 text-[0.65rem] font-bold text-[#63301b]">خصم محسوب: {calculatedDiscount || "—"}%</p></div><div><Label>المدة</Label><Input inputMode="numeric" value={durationDays} onChange={event => setDurationDays(event.target.value.replace(/\D/g, ""))} className="mt-1 h-9" /></div></div></div></div><div className={`mt-3 rounded-xl px-3 py-2 text-xs font-bold ${expired ? "bg-red-50 text-red-700" : "bg-emerald-50 text-emerald-700"}`}>{expired ? "منتهي — أُزيل من واجهة العملاء" : daysRemaining !== null ? <><span>متبقٍ: {daysRemaining} {daysRemaining === 1 ? "يوم" : "أيام"}</span>{expiresAt ? <span className="mr-2 font-medium text-slate-500">· ينتهي في {expiresAt.toLocaleDateString("ar-SY", { year: "numeric", month: "long", day: "numeric" })}</span> : null}</> : "عرض قديم بلا مدة؛ حدّثه قبل طلب تمييزه."}</div><div className="mt-3 flex flex-wrap gap-2"><button onClick={() => setActive(value => !value)} className={`rounded-lg px-3 py-2 text-xs font-bold ${active ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-500"}`}>{active ? "العرض نشط" : "العرض موقوف"}</button><button disabled={saving || !catalogItemId || text.trim().length < 3 || Number(durationDays) < 1 || Number(durationDays) > 365 || !validOfferPrice} onClick={() => onUpdate({ id: offer.id, storeId, catalogItemId: Number(catalogItemId), text: text.trim(), imageUrl: offer.imageUrl ?? "", imageStorageKey: offer.imageStorageKey ?? "", durationDays: Number(durationDays), offerPrice: offerPriceNew, active })} className="rounded-lg bg-rose-50 px-3 py-2 text-xs font-bold text-[#63301b]">حفظ البطاقة</button><button disabled={deleting} onClick={() => onRemove(offer.id)} className="mr-auto rounded-lg bg-red-50 px-3 py-2 text-red-600"><Trash2 className="h-4 w-4" /></button></div></article>;
}

function OfferArtworkPreview({ product, storeName, title, offerPrice, customImage, compact = false }: { product: PartnerProduct | null; storeName: string; title: string; offerPrice?: number; customImage?: string; compact?: boolean }) {
  const originalPrice = product?.unitPrice ?? 0;
  const finalPrice = offerPrice && offerPrice > 0 ? offerPrice : 0;
  const discountPercent = originalPrice > 0 && finalPrice > 0 ? Math.round((originalPrice - finalPrice) * 100 / originalPrice) : 0;
  const image = customImage || product?.imageUrl || "";
  return <article className={`lahza-offer-artwork ${compact ? "lahza-offer-artwork-compact" : ""}`}><div className="lahza-offer-artwork-glow" /><span className="lahza-offer-artwork-brand">لحظة</span><span className="lahza-offer-artwork-badge">خصم {discountPercent || "—"}%</span><div className="lahza-offer-artwork-copy"><small>{storeName}</small><strong>{title}</strong>{product ? <span>{product.name}</span> : <span>اختر المنتج لتظهر صورته وسعره</span>}<div className="lahza-offer-artwork-prices">{originalPrice > 0 ? <span className="lahza-offer-price-old"><i>قبل العرض</i><del>{formatSyp(originalPrice)}</del></span> : null}{finalPrice > 0 ? <span className="lahza-offer-price-new"><i>فقط</i><b>{formatSyp(finalPrice)}</b></span> : null}</div></div><div className="lahza-offer-artwork-product">{image ? <><img src={image} alt={product?.name ?? "صورة العرض"} /><span className="lahza-offer-phosphor-layer" aria-hidden="true" /></> : <ImageIcon className="h-12 w-12" />}</div></article>;
}

function ImageThumbnail({ src, alt, onPreview }: { src?: string | null; alt: string; onPreview: (src: string, alt: string) => void }) {
  if (!src) return <span className="grid h-[76px] w-[76px] shrink-0 place-items-center rounded-xl bg-slate-100 text-slate-400"><ImageIcon className="h-5 w-5" /></span>;
  return <button type="button" onClick={() => onPreview(src, alt)} className="h-[76px] w-[76px] shrink-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm transition hover:scale-105 focus:outline-none focus:ring-2 focus:ring-[#e95e2a]" title="تكبير الصورة"><img src={src} alt={alt} className="h-full w-full object-cover" /></button>;
}

function FeaturedOffersPanel({ offers, submitting, onRequest }: { offers: PartnerOffer[]; submitting: boolean; onRequest: (offer: PartnerOffer) => void }) {
  const eligibleOffers = offers.filter(offer => offer.active && offer.featuredStatus !== "none" && (!offer.expiresAt || new Date(offer.expiresAt).getTime() > Date.now()));
  const statusCopy: Record<PartnerOffer["featuredStatus"], { label: string; className: string }> = {
    none: { label: "غير مطلوب بعد", className: "bg-slate-100 text-slate-600" },
    pending: { label: "بانتظار موافقة المالك", className: "bg-amber-100 text-amber-900" },
    approved: { label: "معتمد ويظهر في الواجهة", className: "bg-emerald-100 text-emerald-800" },
    rejected: { label: "لم يُعتمد بعد", className: "bg-red-100 text-red-700" },
  };
  return <section className="space-y-5"><section className="rounded-3xl border border-amber-200 bg-gradient-to-l from-amber-50 to-white p-5"><div className="flex items-start gap-3"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-amber-500 text-white"><BadgePercent className="h-5 w-5" /></span><div><h2 className="text-lg font-black text-[#4a2618]">العروض المميزة</h2><p className="mt-1 text-sm leading-6 text-slate-600">أنشئ العرض المميز من النموذج أعلاه وأرسله للمالك. بعد الاعتماد فقط يظهر في شريط العروض وصفحة العروض المميزة.</p></div></div></section>{eligibleOffers.length ? <div className="space-y-3">{eligibleOffers.map(offer => { const status = statusCopy[offer.featuredStatus]; return <article key={offer.id} className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex items-start gap-3">{offer.imageUrl ? <img src={offer.imageUrl} alt="" className="h-16 w-16 rounded-xl object-cover" /> : <span className="grid h-16 w-16 place-items-center rounded-xl bg-amber-50 text-amber-600"><BadgePercent className="h-5 w-5" /></span>}<div className="min-w-0 flex-1"><strong className="block text-base text-[#4a2618]">{offer.text}</strong><span className={`mt-2 inline-flex rounded-full px-3 py-1 text-xs font-bold ${status.className}`}>{status.label}</span>{offer.featuredStatus === "rejected" && offer.featuredReviewNote ? <p className="mt-2 text-xs leading-5 text-red-700">ملاحظة المالك: {offer.featuredReviewNote}</p> : null}</div></div>{offer.featuredStatus !== "pending" && offer.featuredStatus !== "approved" ? <Button disabled={submitting} onClick={() => onRequest(offer)} className="mt-4 rounded-xl bg-amber-500 text-white hover:bg-amber-600"><BadgePercent className="h-4 w-4" /> {offer.featuredStatus === "rejected" ? "إعادة طلب التمييز" : "طلب عرض مميز"}</Button> : null}</article>; })}</div> : <section className="rounded-3xl border border-dashed border-slate-200 bg-white p-8 text-center"><BadgePercent className="mx-auto h-8 w-8 text-slate-400" /><strong className="mt-3 block text-[#4a2618]">لا توجد عروض مميزة قيد المراجعة أو معتمدة</strong><p className="mt-2 text-sm text-slate-500">استخدم النموذج أعلاه لإنشاء عرض مميز جديد وإرساله إلى المالك.</p></section>}</section>;
}

function WorkReportPanel({ report, loading, error }: { report?: WorkReport; loading: boolean; error?: string }) {
  if (loading) return <section className="rounded-3xl bg-white p-8"><Loading text="جارٍ إعداد تقرير العمل..." /></section>;
  if (error) return <section className="rounded-3xl border border-red-200 bg-red-50 p-6 text-sm font-bold text-red-700">تعذر تحميل التقرير: {error}</section>;
  if (!report) return <section className="rounded-3xl bg-white p-8 text-center text-sm text-slate-500">لا تتوفر بيانات تقرير العمل حالياً.</section>;
  const period = `${new Date(report.periodStart).toLocaleDateString("ar-SY")} — ${new Date(report.periodEnd).toLocaleDateString("ar-SY")}`;
  const cards = [{ label: "الطلبات", value: report.current.orders }, { label: "المكتملة", value: report.current.completed }, { label: "الملغاة/المرفوضة", value: report.current.cancelled }, { label: "المبيعات", value: `${report.current.sales} ل.س` }, { label: "زيارات المتجر", value: report.visits }, { label: "زيارات QR", value: report.qrVisits }];
  return <section className="space-y-4"><section className="rounded-3xl bg-gradient-to-l from-[#4a2618] to-[#7a3b1d] p-5 text-white"><div className="flex items-center gap-3"><FileText className="h-7 w-7" /><div><h2 className="text-xl font-black">تقرير العمل</h2><p className="mt-1 text-xs text-rose-100">ملخص متجرك خلال {period}</p></div></div><p className="mt-3 text-sm text-rose-100">الأرقام تخص المتجر أو المتاجر المرتبطة بحسابك فقط.</p></section><div className="grid grid-cols-2 gap-3 sm:grid-cols-3">{cards.map(card => <article key={card.label} className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs font-bold text-slate-500">{card.label}</p><strong className="mt-2 block text-xl font-black text-[#4a2618]">{card.value}</strong></article>)}</div><section className="rounded-3xl border border-slate-200 bg-white p-5"><h3 className="font-black text-[#4a2618]">المنتجات الأكثر طلباً</h3>{report.current.topProducts.length ? <div className="mt-3 space-y-2">{report.current.topProducts.map(product => <div key={product.name} className="flex items-center justify-between rounded-xl bg-slate-50 px-3 py-2 text-sm"><span className="font-bold text-slate-700">{product.name}</span><span className="font-black text-[#63301b]">{product.quantity}</span></div>)}</div> : <p className="mt-3 text-sm text-slate-500">لا توجد طلبات منتجات خلال هذه الفترة.</p>}</section><section className="rounded-3xl border border-rose-100 bg-rose-50 p-4 text-sm text-[#4a2618]">مقارنة بالأسبوع السابق: {report.current.orders - report.previous.orders >= 0 ? "+" : ""}{report.current.orders - report.previous.orders} طلب، و{report.current.sales - report.previous.sales >= 0 ? "+" : ""}{report.current.sales - report.previous.sales} ل.س في المبيعات.</section></section>;
}
function ImagePreview({ preview, onClose }: { preview: { src: string; alt: string } | null; onClose: () => void }) {
  return <Dialog open={Boolean(preview)} onOpenChange={open => { if (!open) onClose(); }}><DialogContent dir="rtl" className="max-w-3xl rounded-3xl border-0 bg-slate-950 p-3 text-white"><DialogHeader><DialogTitle className="sr-only">تكبير الصورة</DialogTitle></DialogHeader>{preview ? <><button type="button" onClick={onClose} className="absolute left-4 top-4 z-10 grid h-10 w-10 place-items-center rounded-full bg-white/15 text-white backdrop-blur hover:bg-white/25"><X className="h-5 w-5" /></button><img src={preview.src} alt={preview.alt} className="mx-auto max-h-[75vh] max-w-full rounded-2xl object-contain" /></> : null}</DialogContent></Dialog>;
}

function StoreHoursDialog({ open, onOpenChange, value, saving, onSave }: { open: boolean; onOpenChange: (open: boolean) => void; value: StoreHours; saving: boolean; onSave: (hours: StoreHours) => void }) {
  const [draft, setDraft] = useState<StoreHours>(value);
  useEffect(() => { if (open) setDraft(value); }, [open, value]);
  const updateDay = (day: keyof StoreHours, patch: Partial<StoreHours[keyof StoreHours]>) => setDraft(current => ({ ...current, [day]: { ...current[day], ...patch } }));
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent dir="rtl" className="max-h-[90vh] w-[calc(100%-1rem)] max-w-2xl overflow-y-auto rounded-3xl bg-white"><DialogHeader><DialogTitle className="text-right text-xl font-black text-[#4a2618]">ساعات العمل</DialogTitle></DialogHeader><p className="text-sm leading-6 text-slate-500">حدد وقت فتح وإغلاق المتجر لكل يوم. يفتح المتجر تلقائياً ضمن الوقت المحدد ويغلق خارجه.</p><div className="mt-3 space-y-2">{STORE_DAY_KEYS.map(day => { const hours = draft[day]; return <div key={day} className={`grid items-center gap-2 rounded-2xl border p-3 ${hours.closed ? "border-slate-200 bg-slate-50" : "border-rose-100 bg-rose-50/40"} sm:grid-cols-[1fr_auto_auto_auto]`}><strong className="text-sm text-[#4a2618]">{STORE_DAY_LABELS[day]}</strong><label className="flex items-center gap-2 text-xs font-bold text-slate-600"><input type="checkbox" checked={hours.closed} onChange={event => updateDay(day, { closed: event.target.checked })} /> مغلق</label><label className="flex items-center gap-2 text-xs font-bold text-slate-600">من <Input type="time" value={hours.from} disabled={hours.closed} onChange={event => updateDay(day, { from: event.target.value })} className="h-9 w-28 bg-white" /></label><label className="flex items-center gap-2 text-xs font-bold text-slate-600">إلى <Input type="time" value={hours.to} disabled={hours.closed} onChange={event => updateDay(day, { to: event.target.value })} className="h-9 w-28 bg-white" /></label></div>; })}</div><div className="mt-5 flex gap-2"><Button type="button" variant="outline" onClick={() => onOpenChange(false)} className="flex-1 rounded-2xl">إلغاء</Button><Button type="button" disabled={saving} onClick={() => onSave(draft)} className="flex-1 rounded-2xl bg-[#4a2618] hover:bg-[#63301b]">{saving ? "جارٍ الحفظ..." : "حفظ ساعات العمل"}</Button></div></DialogContent></Dialog>;
}

function TabButton({ active, danger, icon, children, onClick }: { active: boolean; danger?: boolean; icon: React.ReactNode; children: React.ReactNode; onClick: () => void }) { return <button onClick={onClick} className={`flex items-center justify-center gap-2 rounded-2xl px-4 py-3 text-sm font-black transition ${active ? danger ? "bg-red-600 text-white" : "bg-[#4a2618] text-white" : "bg-slate-50 text-slate-500"}`}>{icon}{children}</button>; }
function EmptyStores() { return <section className="rounded-3xl border border-dashed border-slate-200 bg-white p-8 text-center"><Store className="mx-auto h-8 w-8 text-slate-400" /><h2 className="mt-3 text-lg font-black text-[#4a2618]">لم يُعيّن لك متجر بعد</h2><p className="mt-2 text-sm leading-7 text-slate-500">تواصل مع مالك لحظة ليحدد لك المتجر الذي ستدير منتجاته.</p></section>; }
function Loading({ text }: { text: string }) { return <p dir="rtl" className="mt-4 flex items-center justify-center gap-2 text-sm text-slate-500"><Loader2 className="h-4 w-4 animate-spin" />{text}</p>; }
